/* ==UserStyle==
@name           Click Glow Effect
@namespace      majestic
@version        1.0.0
@author         @Majestic
@description    Glow effect when clicking links and hashtags.
==/UserStyle== */

@keyframes clickGlow {
    0% {
        text-shadow: 0 0 0 transparent;
        filter: brightness(1);
    }

    30% {
        text-shadow:
            0 0 4px currentColor,
            0 0 10px currentColor,
            0 0 20px currentColor,
            0 0 35px currentColor;
        filter: brightness(1.8);
    }

    100% {
        text-shadow: 0 0 0 transparent;
        filter: brightness(1);
    }
}

/* Linki */
a:active {
    animation: clickGlow 0.5s ease-out !important;
}

/* Hashtagi */
[href^="#"]:active,
[class*="hashtag"]:active,
[class*="HashTag"]:active {
    animation: clickGlow 0.5s ease-out !important;
}
